import java.util.*;
public class B {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalChars = scanner.nextInt();
        scanner.nextLine();
        String lineInput = scanner.nextLine();

        int maxWordLength = 0;
        int bracketsCount = 0;
        boolean inBracket = false;
        boolean inBracketWordFlag = false;
        int currentWordLength = 0;
        int maxWordSoFar = 0;

        for (int index = 0; index < totalChars; index++) {
            char ch = lineInput.charAt(index);
            if (ch == '(') {
                if (currentWordLength > maxWordSoFar) {
                    maxWordSoFar = currentWordLength;
                }
                currentWordLength = 0;
                inBracket = true;
            } else if (ch == ')') {
                inBracket = false;
                if (inBracketWordFlag) {
                    bracketsCount++;
                }
                inBracketWordFlag = false;
            } else if (ch == '_') {
                if (currentWordLength > maxWordSoFar) {
                    maxWordSoFar = currentWordLength;
                }
                currentWordLength = 0;
                if (inBracketWordFlag) {
                    bracketsCount++;
                    inBracketWordFlag = false;
                }
            } else {
                if (inBracket) {
                    inBracketWordFlag = true;
                } else {
                    currentWordLength++;
                }
            }
        }
        if (currentWordLength > maxWordSoFar) {
            maxWordSoFar = currentWordLength;
        }
        System.out.println(maxWordSoFar + " " + bracketsCount);
    }
}
